Send SMS.code:
// Send an SMS to one phone number.
// The project ID and API key come from the credential.
send({
  // Recipient in international format.
  to_number: $.data.phone,
  content: 'Your child is due for the measles vaccine on Monday at Kibera Health Centre.',
});

Send Appointment Reminder.code:
// Send a personalised appointment reminder.
send({
  to_number: $.data.phone,
  content: `Hello ${$.data.firstName}, your clinic appointment is on ${$.data.appointmentDate}. Reply 1 to confirm.`,
  // ID of the phone or route to send from (e.g. PN...).
  route_id: $.data.routeId,
  // Optional: webhook notified when the message status changes.
  status_url: 'https://app.openfn.org/i/your-webhook-id',
  // Optional: custom variables stored with the message for reporting.
  vars: { programme: 'ANC', facility_code: $.data.facilityCode },
});

Send Message to Contact.code:
// Send to an existing contact and fill in [[contact.*]] variables.
send({
  // Telerivet contact ID (e.g. CT...).
  contact_id: $.data.contactId,
  content: 'Hi [[contact.name]], your cash transfer of KES 3,000 has been sent.',
  // Evaluate [[...]] variables in the content.
  replace_variables: true,
});

Send Voice Call.code:
// Place a text-to-speech voice call.
send({
  to_number: $.data.phone,
  message_type: 'call',
  // Spoken during the call.
  content: 'This is a reminder that the distribution takes place tomorrow at the community hall.',
  tts_lang: 'en-US',
  tts_voice: 'female',
});
